root.command:

IF OBJECT_ID(N'dbo.ContactDeliverToAddressTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.ContactDeliverToAddressTbl', N'CreatedDate') IS NULL
    ALTER TABLE dbo.ContactDeliverToAddressTbl ADD CreatedDate DATETIME NOT NULL CONSTRAINT DF_ContactDeliverToAddress_CreatedDate DEFAULT (GETDATE());
IF OBJECT_ID(N'dbo.ContactDeliverToAddressTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.ContactDeliverToAddressTbl', N'LastUsedDate') IS NULL
    ALTER TABLE dbo.ContactDeliverToAddressTbl ADD LastUsedDate DATETIME NULL;
